      float pattern = bands * a + radial_freq * r + t;
      float v = sin(pattern);

      // Now, we can use the angle and time to create a hue that shifts.
      float hue = (a + iTime) / (2.0 * 3.14159); // normalized angle plus time shift
      vec3 color = hsv2rgb(vec3(hue, 1.0, 1.0));

