      float v = sin(pattern * 2.0); // to get more bands? or not

      // Create two colors: one for positive and one for negative
      vec3 color1 = vec3(1.0, 0.0, 1.0); // magenta
      vec3 color2 = vec3(0.0, 1.0, 1.0); // cyan

      vec3 color = mix(color1, color2, smoothstep(-0.5, 0.5, v));

