Here's a hypnotic spiral animation shader for Shadertoy with smooth color transitions, rotation, and pulsating effects. The spiral dynamically shifts colors while rotating inward, creating a mesmerizing effect:

```glsl
#define PI 3.14159265359

// HSV to RGB conversion function
vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalize coordinates with aspect ratio correction
    vec2 uv = (fragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    float r = length(uv);
    float a = atan(uv.y, uv.x);

    // Time variables for animation
    float t = iTime * 0.5;          // Base time
    float pulse = sin(iTime * 2.0) * 0.1 + 0.9;  // Pulsation effect

    // Spiral parameters
    float bands = 12.0 + sin(iTime * 0.3) * 3.0;  // Dynamic band count
    float radial_freq = 80.0 * pulse;              // Pulsating frequency
    float rotation = t * 3.0;                      // Rotation speed

    // Create spiral pattern
    float pattern = bands * a + radial_freq * r + rotation;
    float wave = sin(pattern) * 0.5 + 0.5;

    // Create band mask with smooth edges
    float band_mask = smoothstep(0.1, 0.9, abs(wave - 0.5) * 2.0);

    // Base hue from angle and time (shifts over time)
    float hue = (a + iTime * 0.1) / (2.0 * PI);
    hue = fract(hue + sin(iTime * 0.7) * 0.1);  // Additional hue drift

    // Modify hue for bands (complementary colors)
    hue = mix(hue, hue + 0.5, band_mask * 0.7);

    // Saturation and brightness based on band position
    float sat = mix(0.4, 1.0, band_mask * 0.8 + r * 0.3);
    float val = mix(0.3, 1.0, band_mask * 0.9 - r * 0.2);

    // Apply HSV to RGB conversion
    vec3 color = hsv2rgb(vec3(hue, sat, val));

    // Vignette effect (darken edges)
    float vignette = 1.0 - smoothstep(0.7, 1.1, r);
    color *= vignette * 1.2;  // Boost center brightness

    // Final output with subtle noise for organic feel
    float noise = sin(dot(uv + t, vec2(12.9898, 78.233))) * 0.01;
    fragColor = vec4(color + noise, 1.0);
}
